  if (state === 'cancelled') {
    return {
      ...result,
      exitCode: 130,
      timedOut: false,
      timeoutKind: null,
      terminalReason: 'aborted',
      failureKind: result.failureKind === 'none' ? 'unknown' : result.failureKind,
    };
